local addonName, ns = ...

-- Recipes by reagent and by output over ns.Recipes (Data/Recipes.lua, generated by
-- tools/wowf/recipe_catalog.py from the Forever game tables), built on first use. A row is
--   { professionSkillLine, minRank, yellowAt, greyAt, flags, outputItemID, outputCount,
--     reagentItemID1, count1, reagentItemID2, count2, ... }
-- flags: 1 = added after Classic (unconfirmed on Forever until seen), 2 = output binds on pickup.
-- Filters (all optional): { professions = { [skillLine] = true }, known = "any" | "char",
--   confirmed = true }. Confirmed = a Classic recipe, or a newer one that a character knows or
--   whose output was seen on the Auction House. (A profession window listing a recipe proves
--   nothing: GetAllRecipeIDs lists Season-of-Discovery recipes too [F-123].)

local L = ns.L
local RecipeIndex = {}
ns.RecipeIndex = RecipeIndex

local FLAG_NEW, FLAG_BOP = 1, 2
local PROFESSION, MIN_RANK, YELLOW, GREY, FLAGS, OUTPUT, COUNT, FIRST_REAGENT = 1, 2, 3, 4, 5, 6, 7, 8
local PRINT_LIMIT = 20

local byReagent, byOutput, total

local function Add(map, key, recipeID)
    local list = map[key]
    if not list then
        list = {}
        map[key] = list
    end
    list[#list + 1] = recipeID
end

local function Ensure()
    if byReagent then return end
    byReagent, byOutput, total = {}, {}, 0
    for recipeID, r in pairs(ns.Recipes or {}) do
        total = total + 1
        Add(byOutput, r[OUTPUT], recipeID)
        for i = FIRST_REAGENT, #r, 2 do Add(byReagent, r[i], recipeID) end
    end
    for _, list in pairs(byReagent) do table.sort(list) end
    for _, list in pairs(byOutput) do table.sort(list) end
end

-- A readable copy of one recipe, or nil.
function RecipeIndex.Get(recipeID)
    local r = ns.Recipes and ns.Recipes[recipeID]
    if not r then return nil end
    local reagents = {}
    for i = FIRST_REAGENT, #r, 2 do reagents[#reagents + 1] = { itemID = r[i], count = r[i + 1] } end
    return {
        recipeID = recipeID, profession = r[PROFESSION], minRank = r[MIN_RANK], yellow = r[YELLOW], grey = r[GREY],
        new = bit.band(r[FLAGS], FLAG_NEW) ~= 0, bop = bit.band(r[FLAGS], FLAG_BOP) ~= 0,
        output = r[OUTPUT], count = r[COUNT], reagents = reagents,
    }
end

-- Known by this character ("char") or by any character of the account ("any").
function RecipeIndex.IsKnown(recipeID, who)
    local known = ns.db and ns.db.recipesKnown
    if not known then return false end
    if who == "char" then
        local key = ns.CharKey()
        return key ~= nil and known[key] ~= nil and known[key][recipeID] == true
    end
    for _, set in pairs(known) do
        if set[recipeID] then return true end
    end
    return false
end

function RecipeIndex.IsConfirmed(recipeID)
    local r = ns.Recipes and ns.Recipes[recipeID]
    if not r then return false end
    if bit.band(r[FLAGS], FLAG_NEW) == 0 then return true end
    if RecipeIndex.IsKnown(recipeID, "any") then return true end
    return ns.PriceDB.Get(r[OUTPUT]) ~= nil
end

function RecipeIndex.Matches(recipeID, filter)
    if not filter then return true end
    local r = ns.Recipes and ns.Recipes[recipeID]
    if not r then return false end
    if filter.professions and not filter.professions[r[PROFESSION]] then return false end
    if filter.known and not RecipeIndex.IsKnown(recipeID, filter.known) then return false end
    if filter.confirmed and not RecipeIndex.IsConfirmed(recipeID) then return false end
    return true
end

local function Filtered(list, filter)
    local out = {}
    for _, recipeID in ipairs(list or {}) do
        if RecipeIndex.Matches(recipeID, filter) then out[#out + 1] = recipeID end
    end
    return out
end

-- Recipe IDs that use the item as a reagent / that make it, sorted.
function RecipeIndex.UsingReagent(itemID, filter)
    Ensure()
    return Filtered(byReagent[itemID], filter)
end

function RecipeIndex.Making(itemID, filter)
    Ensure()
    return Filtered(byOutput[itemID], filter)
end

-- Recipes that use any of the items (the reagent tray), each once, sorted.
function RecipeIndex.UsingAny(itemIDs, filter)
    Ensure()
    local seen, out = {}, {}
    for _, itemID in ipairs(itemIDs) do
        for _, recipeID in ipairs(byReagent[itemID] or {}) do
            if not seen[recipeID] then
                seen[recipeID] = true
                if RecipeIndex.Matches(recipeID, filter) then out[#out + 1] = recipeID end
            end
        end
    end
    table.sort(out)
    return out
end

-- Recipes whose every reagent a vendor sells (isVendorSold(itemID) truthy), filtered, sorted.
function RecipeIndex.FromVendorGoods(isVendorSold, filter)
    local out = {}
    for recipeID, r in pairs(ns.Recipes or {}) do
        local all = true
        for i = FIRST_REAGENT, #r, 2 do
            if not isVendorSold(r[i]) then
                all = false
                break
            end
        end
        if all and RecipeIndex.Matches(recipeID, filter) then out[#out + 1] = recipeID end
    end
    table.sort(out)
    return out
end

function RecipeIndex.Count()
    Ensure()
    return total
end

-- The client's (localized) profession name, or the skill line ID.
function RecipeIndex.ProfessionName(skillLine)
    local ok, name = pcall(C_TradeSkillUI.GetTradeSkillDisplayName, skillLine)
    if ok and type(name) == "string" and name ~= "" then return name end
    return tostring(skillLine)
end

-- Print order: recipes this account knows, then other confirmed ones, then unconfirmed new ones;
-- within each, by profession, skill (yellowAt) and recipe ID.
local function SortForPrint(list)
    local group = {}
    for _, recipeID in ipairs(list) do
        group[recipeID] = RecipeIndex.IsKnown(recipeID, "any") and 0 or (RecipeIndex.IsConfirmed(recipeID) and 1 or 2)
    end
    table.sort(list, function(a, b)
        if group[a] ~= group[b] then return group[a] < group[b] end
        local ra, rb = ns.Recipes[a], ns.Recipes[b]
        if ra[PROFESSION] ~= rb[PROFESSION] then return ra[PROFESSION] < rb[PROFESSION] end
        if ra[YELLOW] ~= rb[YELLOW] then return ra[YELLOW] < rb[YELLOW] end
        return a < b
    end)
    return group
end

-- /bf recipes <item> [all]: what makes and what uses an item, printed once the item names are loaded.
function RecipeIndex.PrintFor(itemID, showAll)
    local uses, makes = RecipeIndex.UsingReagent(itemID), RecipeIndex.Making(itemID)
    local group = SortForPrint(uses)
    SortForPrint(makes)
    local known, new, unconfirmed = 0, 0, 0
    for _, recipeID in ipairs(uses) do
        if group[recipeID] == 0 then known = known + 1 end
        if group[recipeID] == 2 then unconfirmed = unconfirmed + 1 end
        if bit.band(ns.Recipes[recipeID][FLAGS], FLAG_NEW) ~= 0 then new = new + 1 end
    end
    local limit = showAll and math.huge or PRINT_LIMIT
    local ids = { itemID }
    local shown = {}
    for _, list in ipairs({ makes, uses }) do
        for i = 1, math.min(#list, limit) do
            local r = RecipeIndex.Get(list[i])
            shown[#shown + 1] = r
            ids[#ids + 1] = r.output
            for _, g in ipairs(r.reagents) do ids[#ids + 1] = g.itemID end
        end
    end
    ns.Items.Load(ids, function()
        local link = ns.Items.Link(itemID)
        ns.Print(string.format(L["%s: used by %d recipes (%d known, %d new, %d of them unconfirmed), made by %d."], link,
            #uses, known, new, unconfirmed, #makes))
        for _, r in ipairs(shown) do
            local parts = {}
            for _, g in ipairs(r.reagents) do parts[#parts + 1] = g.count .. " x " .. ns.Items.Link(g.itemID) end
            local notes = ""
            if RecipeIndex.IsKnown(r.recipeID, "any") then notes = notes .. " " .. L["(known)"] end
            if r.new and not RecipeIndex.IsConfirmed(r.recipeID) then notes = notes .. " " .. L["(new, unconfirmed)"] end
            ns.Print(string.format("  %s%s x%d - %s %d/%d - %s%s", r.output == itemID and "<- " or "", ns.Items.Link(r.output),
                r.count, RecipeIndex.ProfessionName(r.profession), r.yellow, r.grey, table.concat(parts, ", "), notes))
        end
        local hidden = math.max(0, #uses - limit) + math.max(0, #makes - limit)
        if hidden > 0 then
            ns.Print(string.format(L["  ... and %d more (/bf recipes %d all lists them)."], hidden, itemID))
        end
    end)
end

-- /bf selftest: the generated data against recipes known from the tables (70450).
function RecipeIndex.SelfTest(report)
    local passed, failed = 0, 0
    local function check(name, ok, detail)
        if ok then passed = passed + 1 else failed = failed + 1 end
        report(name, ok, detail)
    end
    check("RECIPES-loaded", RecipeIndex.Count() > 1000,
        string.format("%d recipes from build %s", RecipeIndex.Count(), tostring(ns.RecipesBuild)))
    local bolt = RecipeIndex.Get(2963)
    check("RECIPES-bolt", bolt ~= nil and bolt.output == 2996 and bolt.count == 1 and #bolt.reagents == 1
        and bolt.reagents[1].itemID == 2589 and bolt.reagents[1].count == 2, "Bolt of Linen Cloth = 2 Linen Cloth -> 1 bolt")
    local bronze = RecipeIndex.Get(2659)
    check("RECIPES-bronze", bronze ~= nil and bronze.count == 2, "Smelt Bronze makes 2 bars")
    local transmute = RecipeIndex.Get(11479)
    check("RECIPES-transmute", transmute ~= nil and transmute.count == 1, "Transmute: Iron to Gold makes 1 (count 0 in the tables)")
    check("RECIPES-uses", tContains(RecipeIndex.UsingReagent(2589), 2963), "Linen Cloth is used by Bolt of Linen Cloth")
    check("RECIPES-makes", tContains(RecipeIndex.Making(2841), 2659), "Bronze Bar is made by Smelt Bronze")
    local bad = 0
    for _, r in pairs(ns.Recipes or {}) do
        if #r < FIRST_REAGENT + 1 or (#r - COUNT) % 2 ~= 0 or r[COUNT] < 1 then bad = bad + 1 end
    end
    check("RECIPES-rows", bad == 0, string.format("%d malformed rows", bad))
    check("VENDOR-seed", ns.VendorSeed ~= nil and ns.VendorSeed[2320] == 10, "Coarse Thread costs 10c at a vendor")
    return passed, failed
end
